import unittest
from candidate import sum_to_n

class TestSumToN(unittest.TestCase):
    def test_normal_case_for_30(self):
        self.assertEqual(sum_to_n(30), 465)

    def test_normal_case_for_100(self):
        self.assertEqual(sum_to_n(100), 5050)

    def test_normal_case_for_5(self):
        self.assertEqual(sum_to_n(5), 15)

    def test_normal_case_for_10(self):
        self.assertEqual(sum_to_n(10), 55)

    def test_boundary_condition_for_one(self):
        self.assertEqual(sum_to_n(1), 1)

    def test_boundary_condition_for_zero(self):
        self.assertEqual(sum_to_n(0), 0)

    def test_negative_integer_input(self):
        self.assertEqual(sum_to_n(-5), 0)

    def test_none_value_raises_type_error(self):
        with self.assertRaises(TypeError):
            sum_to_n(None)

    def test_float_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            sum_to_n(5.5)

    def test_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            sum_to_n("10")

    def test_list_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            sum_to_n([1, 2, 3])

    def test_large_positive_integer_boundary(self):
        self.assertEqual(sum_to_n(1000), 500500)

if __name__ == '__main__':
    unittest.main()
